def get_model_metadata(model_id: str) -> Optional[ModelMetadata]:
    """Get metadata for a specific model."""
    for m in MODEL_METADATA:
        if m.id == model_id:
            return m
    return None


def get_models_by_provider(provider: str) -> List[ModelMetadata]:
    """Get all models for a specific provider."""
    return [m for m in MODEL_METADATA if m.provider == provider]


def is_valid_model(model_id: str) -> bool:
    """Check if a string is a valid model identifier."""
    return model_id in ALL_MODELS
